create table if not exists public.organization_settings (organization_id uuid primary key references public.organizations(id) on delete cascade, institute_type text not null default 'school', phone text, email text, address text, logo_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.permissions (id uuid primary key default gen_random_uuid(), code text unique not null, name text not null, module text not null);
create table if not exists public.role_permissions (organization_id uuid not null references public.organizations(id) on delete cascade, role text not null check(role in ('admin','teacher','staff')), permission_id uuid not null references public.permissions(id) on delete cascade, enabled boolean not null default true, primary key(organization_id,role,permission_id));
create table if not exists public.staff_invites (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, email text not null, full_name text not null, role text not null check(role in ('admin','teacher','staff')), invited_by uuid references auth.users(id), created_at timestamptz not null default now(), accepted_at timestamptz);
alter table public.organization_settings enable row level security;
alter table public.permissions enable row level security;
alter table public.role_permissions enable row level security;
alter table public.staff_invites enable row level security;
create policy "settings same org" on public.organization_settings for all using(organization_id=public.user_org_id()) with check(organization_id=public.user_org_id());
create policy "permissions read authenticated" on public.permissions for select to authenticated using(true);
create policy "role permissions same org" on public.role_permissions for all using(organization_id=public.user_org_id()) with check(organization_id=public.user_org_id());
create policy "invites same org" on public.staff_invites for all using(organization_id=public.user_org_id()) with check(organization_id=public.user_org_id());
insert into public.permissions(code,name,module) values ('students.view','View Students','Students'),('students.manage','Manage Students','Students'),('admissions.manage','Manage Admissions','Admissions'),('attendance.view','View Attendance','Attendance'),('attendance.manage','Manage Attendance','Attendance'),('fees.view','View Fees','Fees'),('fees.manage','Manage Fees','Fees'),('fees.receipts','Generate Fee Receipts','Fees'),('exams.view','View Exams','Exams'),('exams.manage','Manage Exams','Exams'),('results.manage','Manage Results','Results'),('notices.manage','Manage Notices','Notices'),('reports.view','View Reports','Reports'),('staff.manage','Manage Staff','Staff'),('settings.manage','Manage Institute Settings','Settings') on conflict(code) do nothing;
